style.css:
body {
  /* URL картинки — замените на нужный путь или ссылку */
  background-image: url("https://i.imgur.com/6p2DlUQ.png");

  /* Повтор изображения по горизонтали/вертикали: no-repeat — не повторять */
  background-repeat: no-repeat;

  /* Положение изображения: по центру */
  background-position: center center;

  /* Размер: cover — масштабирует изображение, чтобы заполнить весь экран, сохраняя пропорции */
  background-size: cover;

  /* Фиксированный фон при скролле: можно убрать, если не нужен */
  background-attachment: fixed;

  /* Запасной цвет на время загрузки или при отсутствии картинки */
  background-color: #111;

  /* Обеспечивает, что тело займёт всю высоту экрана */
  min-height: 100vh;
  margin: 0;
}
